function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt;if(p.life<=0)particles.splice(i,1);}}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function text(s,x,y,size=14,color='#f3e8c9',font="'DM Mono', monospace",align='left'){ctx.fillStyle=color;ctx.font=`${size}px ${font}`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(s,x,y);}
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function worldDraw(){ctx.save();ctx.translate(-Math.floor(camera.x),-Math.floor(camera.y));
 // building floor and subtly gridded tiles
 rect(0,0,world.w,world.h,'#101819');rect(0,floorY,world.w,floorH,'#454945');
 for(let x=0;x<world.w;x+=48){rect(x,floorY,1,floorH,'#52564e');rect(x+1,floorY,1,floorH,'#3b403b');}
 for(let y=floorY;y<floorY+floorH;y+=48){rect(0,y,world.w,1,'#59594e');rect(0,y+1,world.w,1,'#3e433e');}
 for(let x=0;x<world.w;x+=96)for(let y=floorY;y<floorY+floorH;y+=96){if((x/96+y/96)%2===0)rect(x+2,y+2,43,43,'#ffffff04');}
 // perimeter walls, with stylized brick pattern
 wall(0,floorY-27,world.w,28);wall(0,floorY+floorH,world.w,28);
 for(let x=0;x<world.w;x+=roomW){wall(x-26,floorY,26,floorH);}
 wall(world.w,floorY,28,floorH);
 for(const boundary of [720,1440]){
  wall(boundary-13,floorY,26,220);wall(boundary-13,410,26,210);
  rect(boundary-20,326,40,90,'#242b28');rect(boundary-14,333,28,76,'#858267');rect(boundary-10,339,20,64,'#34403b');
  rect(boundary-21,320,42,7,'#c7a86f');rect(boundary-21,411,42,7,'#c7a86f');
 }
 // exit windows and evacuation markers
 for(const ex of [65,720,1440,2090]){rect(ex-34,floorY-29,68,31,'#151c1c');rect(ex-28,floorY-23,56,19,'#9bdbd1');rect(ex-25,floorY-20,50,13,'#c7f5df');rect(ex-2,floorY-23,4,19,'#526765');rect(ex-32,floorY+3,64,5,'#efcd71');}
 // room identity stencils
 for(let r=0;r<3;r++){const ox=r*roomW;text(`SECTOR 0${r+1}`,ox+30,floorY+34,11,'#e3d2a077');text(['APARTMENTS','SERVICE WING','NORTH TOWER'][r],ox+30,floorY+52,9,'#c5c7b355');}
 drawProps();drawPickups();drawFires();drawCivilians();drawEnemies();drawShots();drawPlayer();drawParticles();
 ctx.restore();}
function wall(x,y,w,h){rect(x,y,w,h,'#8a8064');rect(x,y,w,h>10?5:w,'#c6ac76');rect(x,y+h-5,w,5,'#5e594a');for(let xx=x+5;xx<x+w;xx+=25){rect(xx,y+9,1,Math.max(0,h-18),'#645f50');}}
function drawProps(){for(const p of props){const x=p.x,y=p.y;ctx.save();ctx.globalAlpha=.35;rect(x-p.w/2+6,y+p.h/2-2,p.w,p.h/3,'#101514');ctx.restore();
 if(p.type==='sofa'){rounded(x-p.w/2,y-p.h/2,p.w,p.h,7,'#654c3e');rounded(x-p.w/2+6,y-p.h/2+6,p.w-12,p.h-13,5,'#987456');rect(x-2,y-p.h/2+7,4,p.h-14,'#5b4439');rect(x-p.w/2+5,y+p.h/2-4,10,5,'#392f29');rect(x+p.w/2-15,y+p.h/2-4,10,5,'#392f29');}
 else if(p.type==='table'){rect(x-p.w/2,y-p.h/2+9,p.w,p.h-15,'#866a45');rect(x-p.w/2+4,y-p.h/2+13,p.w-8,p.h-23,'#aa8954');rect(x-p.w/2+4,y+p.h/2-7,6,9,'#56462f');rect(x+p.w/2-10,y+p.h/2-7,6,9,'#56462f');rect(x-9,y-7,18,14,'#626955');}
 else if(p.type==='cabinet'){rect(x-p.w/2,y-p.h/2,p.w,p.h,'#5a5345');rect(x-p.w/2+4,y-p.h/2+4,p.w-8,p.h-8,'#77715c');rect(x-2,y-p.h/2+7,4,p.h-14,'#48483f');rect(x-14,y,4,4,'#dcc67e');}
 else {rect(x-4,y+12,8,15,'#584838');rect(x-13,y+20,26,4,'#493b30');for(let i=0;i<5;i++){const a=i*1.25+p.seed;ctx.fillStyle=['#5b7b57','#77945e','#3f6753'][i%3];ctx.beginPath();ctx.ellipse(x+Math.cos(a)*12,y+Math.sin(a)*10,7,10,a,0,Math.PI*2);ctx.fill();}}
 }}
function drawFires(){for(const f of fires){if(f.dead)continue;const p=f.phase,scale=1+Math.sin(p)*.12;ctx.save();ctx.translate(f.x,f.y);if(f.block){ctx.globalAlpha=.23;ctx.fillStyle=weapons[fireWeapon(f.type)].color;ctx.beginPath();ctx.arc(0,0,f.r+12,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
 ctx.fillStyle='#ff5a2c';ctx.beginPath();ctx.ellipse(0,6,f.r*1.1,f.r*.78,0,0,Math.PI*2);ctx.fill();
 for(let i=0;i<4;i++){const a=i*Math.PI/2+p*.55;ctx.fillStyle=['#ffb642','#ffe98b','#ee4d2a','#ff8539'][i];ctx.beginPath();ctx.ellipse(Math.cos(a)*f.r*.4,Math.sin(a)*f.r*.35-7,6*scale,rand(10,17)*scale,a,0,Math.PI*2);ctx.fill();}
 ctx.fillStyle='#fff0a5';ctx.fillRect(-3,4,6,8);ctx.restore();
 if(f.block){rect(f.x-20,f.y+f.r+10,40,4,'#24201b');rect(f.x-20,f.y+f.r+10,40*(f.health/4),4,weapons[fireWeapon(f.type)].color);}}
}
function drawCivilians(){for(const c of civilians){if(c.rescued||c.carried)continue;const panic=c.panic;ctx.save();ctx.translate(c.x,c.y);ctx.fillStyle='#1b2220';ctx.beginPath();ctx.ellipse(0,9,10,5,0,0,7);ctx.fill();rect(-6,-8,12,17,'#5d9c8b');rect(-5,-15,10,9,'#dfad75');rect(-7,-17,14,4,'#503a31');rect(-3,-2,6,4,'#e7d2aa');rect(-7,8,4,5,'#282d2b');rect(3,8,4,5,'#282d2b');if(panic>.2){text('!',9,-15,12,'#ffb753');}ctx.restore();}}
function drawEnemies(){for(const e of enemies){if(e.hp<=0)continue;ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle=e.flash>0?'#fff':enemyColor(e.type);ctx.beginPath();ctx.arc(0,0,13+Math.sin(e.phase*4)*1.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#211c21';ctx.beginPath();ctx.arc(-4,-2,2,0,Math.PI*2);ctx.arc(4,-2,2,0,Math.PI*2);ctx.fill();rect(-5,5,10,3,'#ffc075');ctx.strokeStyle=enemyColor(e.type);ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,17,0,Math.PI*2);ctx.stroke();
 for(let i=0;i<3;i++)rect(-8+i*6,20,4,3,i<e.hp?'#f7d96c':'#303333');ctx.restore();}}
function enemyColor(t){return t==='EMBER'?'#d85e35':t==='OIL'?'#ee8e39':t==='FROSTFIRE'?'#73bfd2':'#b0a7e8'}
function drawPickups(){for(const p of pickups){if(p.used)continue;const bob=Math.sin(elapsed*3+p.x)*2;ctx.save();ctx.translate(p.x,p.y+bob);ctx.fillStyle='#111919aa';ctx.beginPath();ctx.arc(0,0,16,0,7);ctx.fill();ctx.strokeStyle=p.type==='coolant'?'#b7f4a1':'#e9d277';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,13,0,7);ctx.stroke();if(p.type==='coolant'){rect(-5,-7,10,14,'#8fe6ae');rect(-3,-10,6,4,'#d7f5ce');rect(-1,-4,2,8,'#f1ffe2');}else{rect(-7,-8,14,16,'#d1b865');rect(-4,-4,8,8,weapons[p.weapon].color);rect(-4,-11,8,3,'#f2df9e');}ctx.restore();}}
function drawShots(){for(const s of shots){ctx.fillStyle=s.color;ctx.globalAlpha=.75;ctx.beginPath();ctx.ellipse(s.x,s.y,6,3,Math.atan2(s.vy,s.vx),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.face);ctx.fillStyle='#141b19aa';ctx.beginPath();ctx.ellipse(0,11,14,8,0,0,7);ctx.fill();if(player.invuln>0&&Math.floor(elapsed*20)%2===0)ctx.globalAlpha=.45;
 // helmet, head and rescue-yellow turnout coat
 rect(-11,-9,21,21,'#d8a82d');rect(-9,-7,17,15,'#edc746');rect(-8,-11,16,8,'#d9aa36');rect(-9,-15,18,8,'#b53830');rect(-6,-19,12,5,'#e04b39');rect(-11,3,22,3,'#fbebad');rect(-7,9,5,5,'#303a35');rect(3,9,5,5,'#303a35');rect(6,-4,8,4,'#ffe986');
 if(player.carry){rect(-7,-26,14,9,'#629c8a');rect(-5,-31,10,6,'#dfa879');rect(-2,-34,5,4,'#5f4438');}ctx.restore();}
function drawParticles(){for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);rect(p.x,p.y,p.size,p.size,p.color);}ctx.globalAlpha=1;}

