@@ -74,8 +74,10 @@
 function resize(){const s=Math.min(innerWidth/W,innerHeight/H);canvas.style.width=`${W*s}px`;canvas.style.height=`${H*s}px`;}
 addEventListener('resize',resize);resize();
 function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height};}
 canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=pointerPos(e);if(state==='title'||state==='dead'||state==='won'){if(state!=='title'||p.y>240)startGame();return;}if(state==='paused'){state='playing';return;}
+ if(e.pointerType==='mouse'){mouse=Object.assign(mouse,p);mouse.down=true;return;}
+ if(p.x>875&&p.y<86){state='paused';return;}if(p.y>H-76&&p.x>W-190){cycleWeapon();return;}if(p.y>H-76&&p.x>W*.40&&p.x<W*.62){interact();return;}
  touches.set(e.pointerId,{start:p,last:p,side:p.x<W*.5?'move':'aim'});updateSticks();});
 canvas.addEventListener('pointermove',e=>{if(touches.has(e.pointerId)){touches.get(e.pointerId).last=pointerPos(e);updateSticks();}else if(e.pointerType==='mouse')mouse=Object.assign(mouse,pointerPos(e));});
 canvas.addEventListener('pointerup',e=>{if(touches.has(e.pointerId)){touches.delete(e.pointerId);updateSticks();}mouse.down=false;});
 canvas.addEventListener('pointercancel',e=>{touches.delete(e.pointerId);updateSticks()});

