function blockedAt(x,y){
 // The sector dividers are solid except at the fire-door opening, and a sealed door blocks it too.
 for(const boundary of [720,1440])if(Math.abs(x-boundary)<18){const door=doors.find(d=>d.x===boundary);if(y<322||y>404||!door?.open)return true;}
 // Furniture and the special fire lines are real obstacles, not just decoration.
 for(const p of props)if(Math.abs(x-p.x)<p.w/2+player.r-3&&Math.abs(y-p.y)<p.h/2+player.r-3)return true;
 for(const f of fires)if(!f.dead&&f.block&&Math.hypot(x-f.x,y-f.y)<f.r+player.r-3)return true;
 return false;
}
function clearBlock(f){return f.block&&!f.dead&&Math.hypot(f.x-player.x,f.y-player.y)<f.r+player.r+4;}

