 function rescueCivilian(){const c=player.carry;if(!c)return;c.rescued=true;c.carried=false;c.x=player.x;c.y=player.y;player.carry=null;saved++;score+=500+Math.max(0,Math.floor((100-heat)*3));setNotice('CIVILIAN EVACUATED  + SCORE');for(let i=0;i<18;i++)particles.push({x:player.x,y:player.y,vx:rand(-60,60),vy:rand(-90,30),life:rand(.35,.8),color:'#d8f16a',size:3});}
 function collect(p){p.used=true;if(p.type==='coolant'){heat=Math.max(0,heat-38);setNotice('COOLANT INJECTED  −38 HEAT');}else{weapons[p.weapon].ammo=Math.min(weapons[p.weapon].ammo+18,60);setNotice(`${weapons[p.weapon].name} CANISTER +18`);}}

